CREATE TABLE ai_usage(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,hold_id TEXT UNIQUE,request_id TEXT,user_id TEXT NOT NULL,date TEXT NOT NULL,tool TEXT NOT NULL,action TEXT NOT NULL,tier TEXT NOT NULL,model TEXT NOT NULL,prompt_tokens INTEGER NOT NULL DEFAULT 0,completion_tokens INTEGER NOT NULL DEFAULT 0,duration_ms INTEGER NOT NULL,result TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
